// AGE multi-campaign READ-ONLY dispatch preflight. Data Tables are observational, NOT atomic reservations.
// All decisions remain HOLD; no recipient-level authorisation or WhatsApp writes are made.
const from=(name)=>$(name).all().map(v=>v.json||{}).filter(v=>Object.keys(v).length);
const campaigns=from('EspoCRM - Read Campaign Configuration');
const batches=from('Chatwoot - Read Native Campaigns');
const portfolios=$input.all().map(v=>v.json||{}).filter(v=>Object.keys(v).length);
const errors=[],now=new Date(),nowMs=now.getTime();
const bad=x=>x&& (x.error!==undefined||x.httpCode>=400||x.statusCode>=400);
if(campaigns.some(bad))errors.push('ESPOCRM_READ_ERROR');
if(batches.some(bad))errors.push('CHATWOOT_READ_ERROR');
if(portfolios.some(bad))errors.push('PORTFOLIO_TABLE_READ_ERROR');
if(!campaigns.length)errors.push('NO_CAMPAIGN_RECORDS_OR_EMPTY_SOURCE');
if(!portfolios.length)errors.push('PORTFOLIO_CONTROL_MISSING');
if(portfolios.length>=51)errors.push('PORTFOLIO_SCAN_INCOMPLETE');
const seenCampaigns=new Set(),seenBatches=new Set(),seenPortfolios=new Set();
const validClock=v=>typeof v==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(v);
const minute=v=>Number(v.slice(0,2))*60+Number(v.slice(3));
function local(iso,zone) {
  const parts=new Intl.DateTimeFormat('en-GB',{timeZone:zone,year:'numeric',month:'2-digit',
    day:'2-digit',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'})
    .formatToParts(new Date(iso));
  const t=Object.fromEntries(parts.filter(v=>v.type!=='literal').map(v=>[v.type,v.value]));
  return {day:t.weekday,date:t.year+'-'+t.month+'-'+t.day,minutes:Number(t.hour)*60+Number(t.minute)};
}
const rows=[],relevant=campaigns.filter(c=>c.ageChannel==='WhatsApp' && String(c.ageProvider||'').toLowerCase().includes('chatwoot'));
for(const c of relevant) {
  const reasons=[],id=String(c.id||'');
  if(!id||seenCampaigns.has(id))reasons.push('DUPLICATE_OR_MISSING_CAMPAIGN_ID');
  seenCampaigns.add(id);
  if(c.status!=='Active')reasons.push('CAMPAIGN_NOT_ACTIVE');
  if(c.ageTrackingEnabled!==true)reasons.push('CAMPAIGN_TRACKING_NOT_ENABLED');
  if(!/^[1-9]\d*$/.test(String(c.ageInboxId||'')))reasons.push('INBOX_NOT_CONFIGURED');
  if(!c.ageTemplateName||!c.ageTemplateLanguage)reasons.push('TEMPLATE_NOT_CONFIGURED');
  if(!Number.isSafeInteger(c.ageDailyLimit)||c.ageDailyLimit<1)reasons.push('DAILY_TARGET_NOT_CONFIGURED');
  if(!Number.isSafeInteger(c.ageMinGapDays)||c.ageMinGapDays<0)reasons.push('MIN_GAP_NOT_CONFIGURED');
  if(!validClock(c.ageWindowStart)||!validClock(c.ageWindowEnd)||
     (validClock(c.ageWindowStart)&&validClock(c.ageWindowEnd)&&minute(c.ageWindowStart)>=minute(c.ageWindowEnd)))
    reasons.push('INVALID_CAMPAIGN_WINDOW');
  if(c.ageSundayOff!==true&&c.ageSundayOff!==false)reasons.push('SUNDAY_POLICY_NOT_CONFIGURED');
  let localTime=null;
  try {
    if(typeof c.ageTimeZone!=='string'||!c.ageTimeZone)throw Error('missing');
    localTime=local(now.toISOString(),c.ageTimeZone);
  } catch {reasons.push('INVALID_OR_MISSING_TIMEZONE');}
  if(localTime) {
    if(c.startDate&&localTime.date<String(c.startDate).slice(0,10))reasons.push('NOT_STARTED');
    if(c.endDate&&localTime.date>String(c.endDate).slice(0,10))reasons.push('ENDED');
    if(c.ageSundayOff===true&&localTime.day==='Sun')reasons.push('SUNDAY_DISABLED');
    if(validClock(c.ageWindowStart)&&validClock(c.ageWindowEnd)&&
       (localTime.minutes<minute(c.ageWindowStart)||localTime.minutes>=minute(c.ageWindowEnd)))
       reasons.push('OUTSIDE_CAMPAIGN_WINDOW');
  }
  rows.push({espoCampaignId:id,name:String(c.name||'').slice(0,80),
    observedStatus:String(c.status||''),windowMatchesNow:reasons.length===0,
    status:reasons.length?'NOT_WINDOW_READY':'WINDOW_MATCH_ONLY',
    reasons,recipientEligibilityChecked:false,templateApprovalChecked:false,
    globalPolicyChecked:false,canSend:false});
}
if(relevant.length!==rows.length)errors.push('CAMPAIGN_REVIEW_INCOMPLETE');
if(rows.some(r=>r.reasons.includes('DUPLICATE_OR_MISSING_CAMPAIGN_ID')))errors.push('INVALID_CAMPAIGN_IDS');
let processingWhatsApp=0,completedWhatsApp=0;
for(const c of batches){
  const id=String(c.id??'');
  if(!id||seenBatches.has(id)){errors.push('INVALID_CHATWOOT_BATCH_IDS');break;}
  seenBatches.add(id);
  if(c.campaign_type==='one_off'&&c.inbox?.channel_type==='Channel::Whatsapp'){
    if(c.campaign_status==='processing')processingWhatsApp++;
    if(c.campaign_status==='completed')completedWhatsApp++;
  }
}
const scopes=[];
for(const p of portfolios.filter(x=>!bad(x)).slice(0,50)){
  const reasons=[],id=String(p.portfolioId||'');
  if(!id||seenPortfolios.has(id))reasons.push('INVALID_OR_DUPLICATE_PORTFOLIO_ID');
  seenPortfolios.add(id);
  if(p.masterSendingEnabled!==true)reasons.push('RECORDED_MASTER_DISABLED');
  if(p.unresolvedCycle!==false||p.activeCycleId)reasons.push('UNRESOLVED_OR_UNKNOWN_CYCLE');
  if(p.priorCycleHistoryVerified!==true)reasons.push('CYCLE_HISTORY_NOT_VERIFIED');
  let remainingHours=null;
  if(p.lastVerifiedBatchCompletedAt){
    const ended=Date.parse(p.lastVerifiedBatchCompletedAt);
    if(!Number.isFinite(ended)||ended>nowMs)reasons.push('INVALID_COMPLETION_TIMESTAMP');
    else{
      remainingHours=Math.max(0,Math.ceil((26*3600000-(nowMs-ended))/3600000));
      if(nowMs-ended<26*3600000)reasons.push('GLOBAL_26_HOUR_GAP');
    }
  }
  // Recorded tier is NOT an independently verified Meta rolling-24h usage ledger.
  reasons.push('PORTFOLIO_CAPACITY_NOT_AUTHORISED_BY_DATA_TABLE');
  scopes.push({portfolioId:id||null,recordedMaster:p.masterSendingEnabled===true,
    global26hRemainingHours:remainingHours,holds:reasons,canSend:false});
}
const blockers=[...new Set([...errors,'RECIPIENT_ELIGIBILITY_AND_DYNAMIC_AUDIENCE_NOT_VERIFIED',
  'IMMUTABLE_BATCH_LABEL_AND_ATTEMPT_MAPPING_NOT_VERIFIED','ATOMIC_RESERVATION_NOT_DEPLOYED',
  'META_PORTFOLIO_ROLLING_CAPACITY_NOT_VERIFIED','CHATWOOT_CAMPAIGN_POST_NOT_AUTHORISED'])];
return [{json:{mode:'DRY_RUN',decision:'HOLD',checkedAt:now.toISOString(),
  architecture:'ESPOCRM_N8N_CHATWOOT_NATIVE_META',cadence:'HOURLY_DESIGN',
  crm:{recordsObserved:campaigns.length,relevantWhatsAppCampaigns:rows.length,
    windowMatchingNow:rows.filter(r=>r.windowMatchesNow).length,campaigns:rows.slice(0,100),
    reportPartial:rows.length>100,recipientCountKnown:false},
  chatwoot:{campaignsObserved:batches.length,processingNativeWhatsApp:processingWhatsApp,
    completedNativeWhatsApp:completedWhatsApp,fullHistoryProven:false},
  portfolio:{recordsObserved:portfolios.length,observations:scopes,
    atomicClaimsPossible:false},
  blockers,selectedRecipients:0,reservationsCreated:0,chatwootCampaignsCreated:0,
  crmAttemptsCreated:0,crmEventsWritten:0,canSend:false,
  nextStep:'Add independently verified CRM eligibility/campaign-attempt bridge, atomic portfolio reservation and Chatwoot batch identity. Never toggle canSend in this workflow.'}}];
